mapper.select:
SELECT o.id FROM `order` o
INNER JOIN `show` s ON o.show_id = s.id
WHERE o.status = ${@com.concert.enums.OrderStatus@PAID_VALUE}
  AND (s.show_time < CURDATE()
       OR (s.show_time = CURDATE() AND s.show_time < CURTIME()))
LIMIT #{limit}

mapper.update:
UPDATE `order`
SET status = ${@com.concert.enums.OrderStatus@REFUNDED_VALUE}, update_time = NOW()
WHERE pickup_code = #{pickupCode}
  AND status = ${@com.concert.enums.OrderStatus@PAID_VALUE}
  AND pickup_code IS NOT NULL

mapper.select:
SELECT o.* FROM `order` o
INNER JOIN `user` u ON o.user_id = u.id
WHERE u.phone = #{phone}
  AND o.status = ${@com.concert.enums.OrderStatus@PAID_VALUE}
  AND o.pickup_code IS NOT NULL
ORDER BY o.create_time DESC
